#!/usr/bin/env node
/**
 * Create a linked git worktree whose git hooks actually fire.
 *
 * WHY THIS EXISTS. `git worktree add` alone produces a worktree where EVERY git hook is silently
 * skipped, and nothing anywhere reports it.
 *
 *   husky sets core.hooksPath to `.husky/_`, a RELATIVE path resolved from each worktree's own root
 *   `.husky/_` is generated by husky and self-ignores via `.husky/_/.gitignore`
 *   -> it is neither tracked nor copied into a new worktree, so the path does not resolve
 *   -> git skips the hook with no warning, no error, and exit code 0
 *
 * Commits and pushes have gone out of such a worktree with pre-commit and pre-push running zero
 * times, leaving CI as the only gate that ran. Worktrees made to isolate work from a concurrent
 * session, including ones a tool creates automatically, are hookless the same way.
 *
 * MECHANISM. Two steps `git worktree add` does not do:
 *
 *   1. Run husky's own bin (`node <main>/node_modules/husky/bin.js`) with cwd set to the new
 *      worktree, regenerating `.husky/_` there. The canonical tool doing its own job, not a
 *      hand-rolled copy that would drift from the installed husky version; no package manager is
 *      invoked, so nothing is installed or fetched.
 *   2. Symlink `node_modules` for every directory of the main worktree that holds both a tracked
 *      `package.json` and an installed `node_modules`. Hooks resolve their tools from those trees,
 *      so a worktree missing one fails on the first command. Symlinked rather than installed: a
 *      real install costs minutes, and the dependency tree is identical by construction.
 *
 * SELF-VERIFYING. Wiring hooks and reporting success without checking is how this failure mode
 * survived in the first place, so the last steps assert that the links read clean to `git status`
 * and that `.husky/_/<hook>` exists and is executable for every tracked hook, failing loudly with
 * the remedy if not.
 *
 * REJECTED: pointing `core.hooksPath` at an absolute path in the main worktree. `.git/config` is
 * shared, so every linked worktree would then run the MAIN worktree's copy of each hook: a hook
 * edit on one branch would silently govern every other branch.
 *
 * USAGE
 *   node scripts/create-worktree.mjs <path> <branch> [--from <ref>]
 *
 * `<path>` resolves against the main worktree root, never cwd. `<branch>` is created when it does
 * not exist (from `--from`, default `HEAD`), and checked out when it does.
 */

import { execFileSync } from "node:child_process";
import { accessSync, constants, existsSync, symlinkSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { trackedHooks } from "./validate-git-hooks-active.mjs";

const USAGE =
  "usage: node scripts/create-worktree.mjs <path> <branch> [--from <ref>]";

const HUSKY_BIN = path.join("node_modules", "husky", "bin.js");

/**
 * Parse CLI arguments. Pure: throws an Error carrying the usage text on bad input.
 *
 * @param {string[]} argv arguments after the script path
 * @returns {{target: string, branch: string, from: string}}
 */
export function parseArgs(argv) {
  const positional = [];
  let from = "HEAD";
  const args = argv.filter((arg) => arg !== "--");
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === "--from") {
      from = args[i + 1];
      if (!from)
        throw new Error(
          `--from needs a value (a commit-ish to branch from).\n${USAGE}`,
        );
      i += 1;
    } else {
      positional.push(args[i]);
    }
  }
  const [target, branch, extra] = positional;
  if (!target || !branch || extra !== undefined) throw new Error(USAGE);
  return { target, branch, from };
}

function git(args, cwd) {
  return execFileSync("git", ["-C", cwd, ...args], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
}

/**
 * Directories of the main worktree whose `node_modules` a new worktree needs: each holds a
 * tracked `package.json` (anything under a `node_modules` excluded) and an installed
 * `node_modules`. Relative to `mainRoot`, `.` for the root, sorted.
 *
 * @param {string} mainRoot the main worktree root
 * @returns {string[]}
 */
export function packageDirectories(mainRoot) {
  const listed = git(
    ["ls-files", "-z", "--", "package.json", "*/package.json"],
    mainRoot,
  );
  const directories = new Set();
  for (const file of listed.split("\0").filter(Boolean)) {
    if (path.basename(file) !== "package.json") continue;
    if (file.split("/").includes("node_modules")) continue;
    const directory = path.dirname(file);
    if (existsSync(path.join(mainRoot, directory, "node_modules")))
      directories.add(directory);
  }
  return [...directories].sort();
}

function resolveMainRoot(scriptRoot) {
  // `--git-common-dir` points at the shared `.git` even from inside a linked worktree, so this
  // names the MAIN worktree in both cases, which is where node_modules and husky live.
  const commonDir = path.resolve(
    scriptRoot,
    git(["rev-parse", "--git-common-dir"], scriptRoot).trim(),
  );
  return path.dirname(commonDir);
}

function branchExists(mainRoot, branch) {
  try {
    git(["rev-parse", "--verify", "--quiet", `refs/heads/${branch}`], mainRoot);
    return true;
  } catch {
    return false;
  }
}

function addWorktree(mainRoot, target, branch, from) {
  const exists = branchExists(mainRoot, branch);
  console.log(`\nCreating worktree at ${target}`);
  console.log(
    `  branch ${branch}${exists ? " (existing)" : ` (new, from ${from})`}`,
  );
  // The only step that touches shared git state; it neither moves HEAD in the current worktree
  // nor reads its working tree, so it is safe alongside a concurrent session.
  const args = exists
    ? ["worktree", "add", target, branch]
    : ["worktree", "add", "-b", branch, target, from];
  try {
    execFileSync("git", ["-C", mainRoot, ...args], { stdio: "inherit" });
  } catch {
    throw new Error("git worktree add failed. Nothing was changed.");
  }
}

function wireHooks(huskyBin, target) {
  console.log("\nWiring git hooks (husky)...");
  let output = "";
  try {
    output = execFileSync(process.execPath, [huskyBin], {
      cwd: target,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    }).trim();
  } catch (error) {
    output =
      `${error.stdout ?? ""}${error.stderr ?? ""}`.trim() || error.message;
  }
  // husky reports its own refusals on stdout and exits 0; the verification step below decides.
  if (output) console.log(`  husky: ${output}`);
}

function linkNodeModules(mainRoot, target) {
  const links = [];
  for (const directory of packageDirectories(mainRoot)) {
    const relative = path.join(directory, "node_modules");
    if (!existsSync(path.join(target, directory))) {
      console.log(
        `  ${directory}/ does not exist on this branch; ${relative} not linked`,
      );
      continue;
    }
    const destination = path.join(target, relative);
    if (existsSync(destination)) continue;
    symlinkSync(path.join(mainRoot, relative), destination, "dir");
    links.push(relative);
    console.log(`Linked ${relative} from the main worktree`);
  }
  return links;
}

function assertLinksIgnored(target, links) {
  if (links.length === 0) return;
  const dirty = git(["status", "--porcelain", "--", ...links], target).trim();
  if (dirty === "") return;
  throw new Error(
    `the node_modules links show up in git status:\n${dirty}\n` +
      "  Ignore them with `node_modules` in .gitignore, WITHOUT a trailing slash: git sees a\n" +
      "  symlink as a file, and `node_modules/` matches directories only. Untracked links would\n" +
      "  be staged by `git add -A` as absolute-path symlinks.",
  );
}

function assertHooksLive(target, hooks) {
  const remedy =
    `  Re-run husky from the new worktree:  cd ${target} && node <main-worktree>/${HUSKY_BIN}\n` +
    "  Git skips every unwired hook silently, which is exactly the failure this script exists\n" +
    "  to prevent. The worktree was created; fix the hooks before committing.";
  for (const hook of hooks) {
    const wrapper = path.join(target, ".husky", "_", hook);
    if (!existsSync(wrapper)) {
      throw new Error(
        `hooks are still not wired: ${wrapper} does not exist.\n${remedy}`,
      );
    }
    try {
      accessSync(wrapper, constants.X_OK);
    } catch {
      throw new Error(
        `${wrapper} exists but is not executable, so git will skip it silently.\n${remedy}`,
      );
    }
  }
}

function run(argv) {
  const { target: rawTarget, branch, from } = parseArgs(argv);
  const scriptRoot = fileURLToPath(new URL("..", import.meta.url));
  const mainRoot = resolveMainRoot(scriptRoot);
  // Relative paths resolve against the main worktree root, so `../featurex` names one directory
  // whichever subdirectory the script was invoked from.
  const target = path.resolve(mainRoot, rawTarget);
  if (existsSync(target)) {
    throw new Error(
      `${target} already exists. Choose another path, or remove it first.`,
    );
  }

  const hooks = trackedHooks(mainRoot);
  const huskyBin = path.join(mainRoot, HUSKY_BIN);
  // Checked before anything is created, so a missing husky leaves the repository untouched.
  if (hooks.length > 0 && !existsSync(huskyBin)) {
    throw new Error(
      `${huskyBin} does not exist, so the tracked hooks (${hooks.join(", ")}) cannot be wired.\n` +
        "  Install dependencies in the main worktree, then re-run:\n" +
        `    ${USAGE.replace("usage: ", "")}`,
    );
  }

  addWorktree(mainRoot, target, branch, from);
  if (hooks.length > 0) wireHooks(huskyBin, target);
  else console.log("\nNo hook is tracked under .husky/; nothing to wire.");
  const links = linkNodeModules(mainRoot, target);
  assertLinksIgnored(target, links);
  assertHooksLive(target, hooks);

  if (hooks.length > 0) {
    console.log(
      `Hooks verified live (.husky/_/: ${hooks.join(", ")} present and executable)`,
    );
  }
  console.log(`\n  cd ${target}\n`);
}

function main(argv) {
  try {
    run(argv);
    return 0;
  } catch (error) {
    console.error(`\n${error.message}\n`);
    return 1;
  }
}

if (
  process.argv[1] &&
  import.meta.url === new URL(`file://${process.argv[1]}`).href
) {
  process.exit(main(process.argv.slice(2)));
}
